// AI-entry hold (PR #102, owner decision 2026-10-28: no invented AI confidence
// policy). While the hold is ON, every NEW entry generated by Eleanor, an
// automation or a strategy is blocked until the owner approves a confidence
// policy. Manual entries and every protective action (CLOSE, PARTIAL_CLOSE,
// MODIFY) keep their own governor rules and are never held here.
//
// Owner decision 2026-11-08: land the hold SWITCHED OFF. It is enabled only by
// ARX_AI_ENTRY_HOLD_ENABLED=true (also 1/on/yes); unset or anything else leaves
// order flow exactly as it was. Read on every call, so a restart is not needed
// in a process whose environment changes.
//
// The hold is independent of the trader's discipline settings: it is raised as
// a trading_halt, which a trader override can never clear.
import type { TradeIntent } from "../riskGovernor/preTrade.js";

export const AI_ENTRY_HOLD_ENV = "ARX_AI_ENTRY_HOLD_ENABLED";
export const AI_ENTRY_POLICY_PENDING =
  "AI_ENTRY_POLICY_PENDING: AI-generated entries are disabled until the owner approves a confidence policy.";

const GENERATED_ORIGINS: ReadonlySet<TradeIntent["origin"]> = new Set(["eleanor", "automation", "strategy"]);

export function aiEntryHoldEnabled(env: Record<string, string | undefined> = process.env): boolean {
  return /^(1|true|on|yes)$/i.test((env[AI_ENTRY_HOLD_ENV] ?? "").trim());
}

/**
 * The hold's reason for this intent, or null when it does not apply.
 * `generatedEntry` marks an entry that carries an AI decision id even though
 * its origin label says manual/api/system (a self-trade command, a decision-
 * linked paper order), so the hold cannot be dodged by the label.
 */
export function aiEntryPolicyReason(
  intent: Pick<TradeIntent, "action" | "origin">,
  opts: { generatedEntry?: boolean; env?: Record<string, string | undefined> } = {},
): string | null {
  if (!aiEntryHoldEnabled(opts.env)) return null;
  if (intent.action !== "OPEN") return null;
  return GENERATED_ORIGINS.has(intent.origin) || opts.generatedEntry === true ? AI_ENTRY_POLICY_PENDING : null;
}
